#' Power and Sample Size
#'
#' 
#' @param data .
#' @param mode .
#' @param design .
#' @param sd .
#' @param effect .
#' @param alpha .
#' @param target .
#' @param sided .
#' @param share .
#' @param ntotal .
#' @param r2 .
#' @param ncov .
#' @param clusters .
#' @param msize .
#' @param rho .
#' @param cv .
#' @param dataOutcome .
#' @param dataCluster .
#' @param dataCovs .
#' @param useData .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$inputs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$res} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$powPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$inputs$asDF}
#'
#' \code{as.data.frame(results$inputs)}
#'
#' @export
expower <- function(
    data,
    mode = "power",
    design = "indiv",
    sd = 1,
    effect = 0.3,
    alpha = 0.05,
    target = 0.8,
    sided = "two",
    share = 0.5,
    ntotal = 200,
    r2 = 0,
    ncov = 0,
    clusters = 40,
    msize = 25,
    rho = 0.05,
    cv = 0,
    dataOutcome,
    dataCluster,
    dataCovs,
    useData = FALSE,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("expower requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dataOutcome)) dataOutcome <- jmvcore::resolveQuo(jmvcore::enquo(dataOutcome))
    if ( ! missing(dataCluster)) dataCluster <- jmvcore::resolveQuo(jmvcore::enquo(dataCluster))
    if ( ! missing(dataCovs)) dataCovs <- jmvcore::resolveQuo(jmvcore::enquo(dataCovs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dataOutcome), dataOutcome, NULL),
            `if`( ! missing(dataCluster), dataCluster, NULL),
            `if`( ! missing(dataCovs), dataCovs, NULL))


    options <- expowerOptions$new(
        mode = mode,
        design = design,
        sd = sd,
        effect = effect,
        alpha = alpha,
        target = target,
        sided = sided,
        share = share,
        ntotal = ntotal,
        r2 = r2,
        ncov = ncov,
        clusters = clusters,
        msize = msize,
        rho = rho,
        cv = cv,
        dataOutcome = dataOutcome,
        dataCluster = dataCluster,
        dataCovs = dataCovs,
        useData = useData,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- expowerClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

